#include <SDL2/SDL.h>
#include <string>
#include <vector>
#include <algorithm>
#include "file_ops.hpp"
int main(int,char**){if(SDL_Init(SDL_INIT_VIDEO|SDL_INIT_GAMECONTROLLER))return 1;SDL_Window*w=SDL_CreateWindow("WiiU File Manager",SDL_WINDOWPOS_CENTERED,SDL_WINDOWPOS_CENTERED,854,480,SDL_WINDOW_SHOWN);if(!w){SDL_Quit();return 1;}SDL_Renderer*r=SDL_CreateRenderer(w,-1,SDL_RENDERER_ACCELERATED);if(!r)r=SDL_CreateRenderer(w,-1,SDL_RENDERER_SOFTWARE);if(!r){SDL_DestroyWindow(w);SDL_Quit();return 1;}std::string path="/vol/external01";std::vector<FileEntry> files;std::string err;size_t sel=0;bool run=true;SDL_Event e;auto refresh=[&](){if(!listDirectory(path,files,err))files.clear();sel=files.empty()?0:std::min(sel,files.size()-1);};refresh();while(run){while(SDL_PollEvent(&e)){if(e.type==SDL_QUIT)run=false;if(e.type==SDL_KEYDOWN){auto k=e.key.keysym.sym;if(k==SDLK_ESCAPE)run=false;if(k==SDLK_UP&&sel)sel--;if(k==SDLK_DOWN&&sel+1<files.size())sel++;if(k==SDLK_TAB){path=path=="/vol/external01"?"/vol/storage_usb01":"/vol/external01";refresh();}if(k==SDLK_RETURN&&sel<files.size()&&files[sel].directory){path=joinPath(path,files[sel].name);refresh();}if(k==SDLK_BACKSPACE){auto p=path.find_last_of('/');if(p!=std::string::npos&&path.size()>1)path=path.substr(0,p);refresh();}}}SDL_SetRenderDrawColor(r,12,22,38,255);SDL_RenderClear(r);SDL_Rect h{0,0,854,58};SDL_SetRenderDrawColor(r,22,76,120,255);SDL_RenderFillRect(r,&h);for(size_t i=0;i<std::min<size_t>(files.size(),14);i++){SDL_Rect row{24,80+(int)i*24,5,10};SDL_SetRenderDrawColor(r,105,180,220,255);SDL_RenderFillRect(r,&row);}if(!files.empty()){SDL_Rect b{18,72+(int)sel*24,818,22};SDL_SetRenderDrawColor(r,38,95,142,255);SDL_RenderFillRect(r,&b);}SDL_RenderPresent(r);SDL_Delay(16);}SDL_DestroyRenderer(r);SDL_DestroyWindow(w);SDL_Quit();return 0;}
